"""Generate auditable hypotheses, never an IK marker-renaming file."""
from pathlib import Path
import json,csv,hashlib,html,collections
D=Path('docs/coach/phase14');P=Path('docs/coach/phase13');D.mkdir(exist_ok=True)
def read(p):return json.loads(p.read_text())
def write(name,data): (D/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
# Manual semantic review, versioned here; naming is NOT anatomical documentation.
RULES={
 '5th_metatarsal_head':('MT5','PLAUSIBLE MAIS NON CONFIRMÉE','tête du 5e métatarsien','pied','MT5 évoque le 5e métatarsien ; site exact et offset cutané non documentés'),
 'calcaneal_tuberosity':('CAL','PLAUSIBLE MAIS NON CONFIRMÉE','tubérosité calcanéenne','pied','CAL évoque le calcanéus ; tubérosité, face et offset non certifiés'),
 'lateral_malleolus':('LMAL','PLAUSIBLE MAIS NON CONFIRMÉE','malléole latérale','jambe','abréviation concordante, pas de table auteur CSV→MarkerSet'),
 'tibial_tuberosity':('_tibial_plateau','AMBIGUË','tubérosité tibiale','jambe','plateau tibial ≠ tubérosité tibiale ; proximité segmentaire seulement, substitution interdite'),
 'lateral_epicondyle':('LFC','PLAUSIBLE MAIS NON CONFIRMÉE','épicondyle latéral (membre inférieur d’après contexte)','cuisse','LFC évoque condyle fémoral latéral ; condyle et épicondyle ne sont pas synonymes exacts'),
 'greater_trochanter':('HJC','AMBIGUË','grand trochanter','cuisse','HJC est un centre virtuel de hanche à origine fémur ; trochanter cutané ≠ centre articulaire, substitution interdite'),
 'ASIC':('ASI','PLAUSIBLE MAIS NON CONFIRMÉE','ASIC : expansion anatomique non explicitée dans README','bassin','ASI évoque ASIS ; ASIC ne doit pas être silencieusement corrigé en ASIS'),
 'sacral_crest':('PSI','AMBIGUË','crête sacrée','bassin','PSI évoque PSIS ; crête sacrée ≠ PSIS certifiée, ambiguïté de palpation'),
 'acromioclavicular_joint':('ACR','PLAUSIBLE MAIS NON CONFIRMÉE','articulation acromio-claviculaire','épaule / tronc','acromion et articulation acromio-claviculaire ne fixent pas le même placement exact'),
 'deltoid_tuberosity':('UA1|UA2|UA3','AMBIGUË','tubérosité deltoïdienne','bras','trois points techniques du bras ; aucune identité anatomique de UA1/2/3 établie'),
 'olecranon':('LEL|MEL|EJC','AMBIGUË','olécrâne','avant-bras / coude','olécrâne ≠ épicondyles ni centre du coude ; candidats régionaux seulement, exclus de toute association'),
 'forearm_centre':('FAsuperior|FAradius|FAulna','AMBIGUË','centre de l’avant-bras : définition opérationnelle inconnue','avant-bras','plusieurs points de surface ; pas de définition du centre ni de leur équivalence'),
 'ulna_head':('FAulna','AMBIGUË','tête ulnaire','avant-bras','FAulna attaché au radius dans XML ; nom seul insuffisant pour identifier un point sur ulna'),
 '5th_metacarpal_head':('','AUCUNE CORRESPONDANCE','tête du 5e métacarpien','main','aucun marqueur du MarkerSet attaché à la main ; ne pas confondre MT5 pied et métacarpien'),
 '2nd_metacarpal_head':('','AUCUNE CORRESPONDANCE','tête du 2e métacarpien','main','pas de marqueur de main dans le MarkerSet inspecté'),
 'temporal_bone':('','AUCUNE CORRESPONDANCE','os temporal','tête','pas de tête indépendante ou marqueur crânien dans le modèle inspecté'),
 '1st_metatarsal_head':('TOE','AMBIGUË','tête du 1er métatarsien','pied','TOE est générique et attaché au calcn ; concurrence avec phalange distale, pas de substitution'),
 'toe_distal_phalanx':('TOE','AMBIGUË','phalange distale d’orteil (orteil non spécifié)','orteil','même candidat TOE que métatarsien1 ; manque définition du point, attaché au calcn et non toes'),
 'Skull_vertex':('','AUCUNE CORRESPONDANCE','vertex crânien','tête','pas de marqueur crânien dans le template')}
def main():
 names=read(P/'review-data.json')['names'];model=read(P/'model-inspection.json');mm={x['name']:x for x in model['markers']};rows=[]
 for n in names:
  side='R' if n.startswith('Right_') else 'L' if n.startswith('Left_') else '';key=n.split('_',1)[1] if side else n
  codes,status,definition,segment,reason=RULES[key];candidates=[side+x for x in codes.split('|')] if codes else []
  assert all(c in mm for c in candidates)
  rows.append({'csv':n,'status':status,'resultStatus':'EN ATTENTE DE VALIDATION HUMAINE' if candidates else 'NON TESTÉ','anatomicalDefinition':definition,'definitionBasis':'traduction du label, PAS protocole de palpation confirmé','bodyRegion':segment,'candidates':[{'opensim':c,'attachedFrame':mm[c]['frame'],'localPositionM':[float(v) for v in mm[c]['location'].split()],'positionMeaning':'XML générique, pas position anatomique S01'} for c in candidates],'source':['phase13/model-inspection.json#'+model['sha256'],'phase13/review-data.json','Michaud v1 README (ne fournit pas de table de correspondance)'],'certainty':'aucune autorité documentaire CSV→MarkerSet identifiée','justification':reason,'ambiguity':reason,'usableForIK':False})
 write('correspondences.json',{'status':'EN ATTENTE DE VALIDATION HUMAINE','scope':'hypothèses revues manuellement ; les candidats ne sont PAS un mapping exécutable','counts':{'CONFIRMÉE PAR DOCUMENTATION':0,**dict(collections.Counter(r['status'] for r in rows))},'rows':rows})
 with (D/'matrix-37x66.csv').open('w') as f:
  w=csv.writer(f,lineterminator='\n');w.writerow(['csv_label']+list(mm))
  for r in rows:w.writerow([r['csv']]+[r['status'] if n in [c['opensim'] for c in r['candidates']] else 'AUCUNE CORRESPONDANCE' for n in mm])
 write('model-markers.json',{'status':'VALIDÉ','scope':'66 définitions XML locales uniquement, aucune admission anatomique','markers':[dict(m,csvCandidates=[r['csv'] for r in rows if m['name'] in [c['opensim'] for c in r['candidates']]]) for m in model['markers']]})
 write('decision.json',{'status':'REFUSÉ','scenario':'C','reason':'documentation insuffisante pour relier rigoureusement CSV et MarkerSet ; incompatibilité biologique non démontrée','confirmedPairs':0,'usableMarkersForIK':[],'IK':'NON TESTÉ','retarget':'NON TESTÉ','runtimeEnabled':False,'allowIK':False,'nextAction':'demander aux auteurs le MarkerSet37 original, mapping/placement, paramètres ScaleTool et repères ; aucun autre template générique ne résout à lui seul ces lacunes'})
 original=D/'original-audit.json'
 if original.exists():
  a=read(original);(D/'dataset-README.md').write_text(a['README'].replace('\r\n','\n'));write('force-audit.json',a['forces'])
  write('anthropometry.json',{'status':'EN ATTENTE DE VALIDATION HUMAINE','scope':'valeurs publiques S01 rapportées par déposant, pas mesures PARISFIT ni paramètres complets individualisés','sourceSHA256':a['participantsFileSHA256'],'sourceColumns':a['participantsColumns'],'documentedS01':a['S01'],'unknown':['stature individuelle (aucune colonne présente)','dimensions anatomiques segmentaires mesurées','largeur absolue anatomique bassin','centres articulaires individuels','inerties individuelles','ordre signé P1/P2/P3 par rapport au XML','procédure complète de scaling et marker registration'],'notRequiredForPureIK':['masse et inerties ne sont pas nécessaires au solveur cinématique ; elles sont nécessaires à la dynamique et à la qualification complète'],'scalingExecutable':False})
 # HTML tables generated from exact metadata, no external JS or runtime integration.
 esc=lambda v:html.escape(str(v))
 s='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>PARISFIT · Phase14</title><style>*{box-sizing:border-box}body{margin:0;background:#edf5ef;color:#163f32;font:16px/1.6 system-ui;overflow-wrap:anywhere}main{max-width:1120px;margin:auto;padding:24px}h1{font-size:clamp(28px,5vw,46px);line-height:1.15}section{background:white;padding:22px;border-radius:18px;margin:22px 0}a{color:#165e47}.tag{display:inline-block;background:#f6d4c6;padding:8px 16px;border-radius:20px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid #ddd}summary{cursor:pointer;font-weight:bold}small{display:block}</style><main><a href="../phase13/index.html">← Phase13</a><p>PARISFIT / COACH RECHERCHE / PHASE14</p><h1>Relier les marqueurs.<br>Pas seulement leurs noms.</h1><p class="tag">Scénario C · documentation insuffisante</p><section><h2>Avons-nous assez d’informations ?</h2><p><b>Non. Utilisation actuelle pour S01/P001 : REFUSÉE.</b> Aucun lien anatomique CSV→MarkerSet n'est confirmé par documentation. Cela ne démontre pas que le modèle est biologiquement incompatible : cela empêche son utilisation rigoureuse en l'état.</p><p><b>IK NON TESTÉE.</b> Aucun renommage automatique, centre inventé ou transfert Rocketbox. Modèle générique ≠ modèle S01.</p></section><section><h2>Ce que l’audit distingue</h2><p>Le dépôt déclare37marqueurs de laboratoire dans le modèle ; le XML en expose66. Des correspondances sémantiques sont plausibles, mais les mains et la tête ne disposent pas de leurs marqueurs dans ce template. Les abréviations de centres articulaires ne doivent jamais absorber des marqueurs cutanés.</p><p>Le README décrit explicitement un modèle <b>générique</b>. Les masses et six facteurs de scaling de S01 sont disponibles dans participants.csv ; leur existence ne constitue pas un modèle individualisé ni une procédure de scaling complète.</p></section><section><h2>Matrice de correspondances</h2><p>37lignes ci-dessous ; <a href="matrix-37x66.csv">matrice intégrale37×66</a> et <a href="model-markers.json">inventaire inverse des66marqueurs</a>. «AUCUNE CORRESPONDANCE» signifie aucune association identifiée dans le périmètre examiné, pas une preuve universelle d’absence.</p><p>Définitions anatomiques ci-dessous : lecture des labels seulement, pas protocole de palpation. Positions : mètres dans le repère local du corps XML générique, jamais coordonnées du laboratoire ni mesures S01.</p>'''
 for r in rows:
  c=' ; '.join(esc(v['opensim'])+' @ '+esc(v['attachedFrame'])+' '+esc(v['localPositionM']) for v in r['candidates']) or '—'
  s+='<details><summary>'+esc(r['csv'])+' · '+esc(r['status'])+'</summary><p>'+esc(r['anatomicalDefinition'])+' · '+esc(r['bodyRegion'])+'</p><p>'+c+'</p><p>'+esc(r['justification'])+'</p><small>Source : XML épinglé et label CSV ; lien auteur NON confirmé. Utilisable pour IK : non.</small></details>'
 s+='</section><section><h2>Dossier, sources et reproduction</h2><ul>'
 for n,title in [('DOCUMENTATION.md','Audit documentaire et provenance'),('FRAMES.md','Axes, unités et transformations'),('ANTHROPOMETRY.md','Individualisation : disponible / inconnu'),('FORCES.md','Audit indépendant des forces'),('DECISION.md','Décision, informations nécessaires et protocole conditionnel'),('AUTHOR-REQUEST.md','Demande précise aux auteurs — non envoyée'),('REPRODUCE.md','Scripts et tests'),('original-audit.json','Inspection originale vérifiée'),('anthropometry.json','Paramètres S01 documentés'),('force-audit.json','Forces : P001 complet et répétitions'),('opencap-comparison.json','Comparaison des modèles alternatifs'),('browser-report.json','Tests de la page'),('correspondences.json','Matrice détaillée'),('decision.json','Porte IK fermée')]:s+='<li><a href="'+n+'">'+title+'</a></li>'
 s+='''</ul><p>VALIDÉ : intégrité et calculs dans leur périmètre technique. EN ATTENTE DE VALIDATION HUMAINE : sémantique anatomique, calibration et registration. NON TESTÉ : IK et retarget. REFUSÉ : utilisation actuelle du modèle pour reconstruire S01.</p></section><footer>Florian Michaud(2026), <a href="https://doi.org/10.5281/zenodo.23979972">dataset v1</a>, CC BY4.0. Analyses et tableaux modifiés par PARISFIT, sans approbation des auteurs. Attribution complète dans le dossier. Rocketbox et les huit exercices inchangés. PR11 brouillon, aucun achat, merge ou déploiement.</footer></main></html>'''
 (D/'index.html').write_text(s)
if __name__=='__main__':main()
